import{_ as e,o as c,c as t,a1 as a}from"./chunks/framework.BKrM4vFX.js";const g=JSON.parse('{"title":"Моки банков, касс и ОФД — матрица возможностей","description":"Сравните возможности 10 mock-адаптеров AXIIOM: банки, платежные сервисы, онлайн-кассы и ОФД, поддерживаемые сценарии и ограничения.","frontmatter":{"sourcePath":"docs/capabilities.md"},"headers":[{"level":1,"title":"Что уже умеет мок — матрица возможностей","slug":"Что-уже-умеет-мок-матрица-возможностей","link":"#Что-уже-умеет-мок-матрица-возможностей","children":[{"level":2,"title":"Банки — эквайринг","slug":"Банки-эквайринг","link":"#Банки-эквайринг","children":[{"level":3,"title":"tbank-mock :3100","slug":"tbank-mock-3100","link":"#tbank-mock-3100","children":[]},{"level":3,"title":"yookassa-mock :3102","slug":"yookassa-mock-3102","link":"#yookassa-mock-3102","children":[]},{"level":3,"title":"alfa-mock :3104","slug":"alfa-mock-3104","link":"#alfa-mock-3104","children":[]},{"level":3,"title":"sber-mock :3105","slug":"sber-mock-3105","link":"#sber-mock-3105","children":[]},{"level":3,"title":"vtb-mock :3106","slug":"vtb-mock-3106","link":"#vtb-mock-3106","children":[]}]},{"level":2,"title":"Кассы и ОФД","slug":"Кассы-и-ОФД","link":"#Кассы-и-ОФД","children":[{"level":3,"title":"kassa-mock :3101 (OFD Ferma)","slug":"kassa-mock-3101-ofd-ferma","link":"#kassa-mock-3101-ofd-ferma","children":[]},{"level":3,"title":"atol-mock :3103","slug":"atol-mock-3103","link":"#atol-mock-3103","children":[]},{"level":3,"title":"first-ofd-mock :3107 (OKassa)","slug":"first-ofd-mock-3107-okassa","link":"#first-ofd-mock-3107-okassa","children":[]},{"level":3,"title":"kontur-ofd-mock :3108","slug":"kontur-ofd-mock-3108","link":"#kontur-ofd-mock-3108","children":[]},{"level":3,"title":"taxcom-mock :3109","slug":"taxcom-mock-3109","link":"#taxcom-mock-3109","children":[]}]},{"level":2,"title":"Общие возможности ядра","slug":"Общие-возможности-ядра","link":"#Общие-возможности-ядра","children":[]}]}],"relativePath":"docs/capabilities.md","filePath":"docs/capabilities.md"}'),i={name:"docs/capabilities.md"};function r(s,o,d,l,n,k){return c(),t("div",null,[...o[0]||(o[0]=[a('<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="Что-уже-умеет-мок-матрица-возможностей" tabindex="-1">Что уже умеет мок — матрица возможностей <a class="header-anchor" href="#Что-уже-умеет-мок-матрица-возможностей" aria-label="Permalink to &quot;Что уже умеет мок — матрица возможностей&quot;">​</a></h1><p>Полная матрица по всем 10 адаптерам. Короткая версия — в <a href="/mock-services/#что-уже-умеет-мок">README</a>, детали — в README каждого сервиса и в гайдах «за 10 минут».</p><blockquote><p>Пометки: см. <a href="./overview#пометки-verify-и-fork">легенду VERIFY/FORK</a> — места, где публичная документация провайдера не раскрывает деталь (VERIFY) или мок сознательно отличается (FORK).</p></blockquote><h2 id="Банки-эквайринг" tabindex="-1">Банки — эквайринг <a class="header-anchor" href="#Банки-эквайринг" aria-label="Permalink to &quot;Банки — эквайринг&quot;">​</a></h2><h3 id="tbank-mock-3100" tabindex="-1">tbank-mock :3100 <a class="header-anchor" href="#tbank-mock-3100" aria-label="Permalink to &quot;tbank-mock :3100&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/v2/{Init,Confirm,Cancel,GetState,CheckOrder,Chargeback,Dispute}</code>, <code>/e2c/v2/*</code>, <code>/av/v1/*</code></li><li><strong>Auth:</strong> Token = sha256, <code>TerminalKey</code> проверяется</li><li><strong>Вебхуки:</strong> подписанные, ответ <code>OK</code>, ретраи, <code>webhook-drop</code>/<code>duplicate</code></li><li><strong>Состояния:</strong> NEW→AUTHORIZED/CONFIRMED/REVERSED/REFUNDED/CANCELED + чарджбэк</li><li><strong>Сценарии:</strong> <code>X-Mock-Scenario</code> (<code>chargeback-after:7d</code>, <code>partial-refund</code>), <code>/mock/time</code></li><li><strong>DX:</strong> код + поле + подсказка + ссылка на доку, OpenAPI 3.1, curl в журнале</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code>, <code>POST /sandboxes</code>, <code>verify-merchant</code></li></ul><h3 id="yookassa-mock-3102" tabindex="-1">yookassa-mock :3102 <a class="header-anchor" href="#yookassa-mock-3102" aria-label="Permalink to &quot;yookassa-mock :3102&quot;">​</a></h3><ul><li><strong>Протокол:</strong> REST <code>/v3/{payments,refunds}</code> + capture/cancel, confirmation страница</li><li><strong>Auth:</strong> Basic Auth + <code>Idempotence-Key</code> (replay того же ключа)</li><li><strong>Вебхуки:</strong> <code>{type,event,object}</code> без подписи, ACK 200, ретраи</li><li><strong>Состояния:</strong> <code>pending → waiting_for_capture → succeeded/canceled</code>, two-stage</li><li><strong>Сценарии:</strong> <code>fail</code>, <code>hang</code>, <code>latency</code>, <code>http-500/504</code>, webhook drop/duplicate</li><li><strong>DX:</strong> <code>{type:error, code, description}</code> + hint/doc, 405/415 пустое тело как у провайдера</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code>, без <code>verify-merchant</code> (вебхуки не подписаны)</li></ul><h3 id="alfa-mock-3104" tabindex="-1">alfa-mock :3104 <a class="header-anchor" href="#alfa-mock-3104" aria-label="Permalink to &quot;alfa-mock :3104&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/payment/rest/{register,registerPreAuth,deposit,reverse,refund,getOrderStatus}.do</code>, form-urlencoded, <code>formUrl</code> + ACS 3DS1/3DS2</li><li><strong>Auth:</strong> <code>userName</code>/<code>password</code> в каждом запросе, синтетические <code>ALFAMOCKTEST</code>/<code>mockpass123</code>, <code>orderNumber</code> уникален → <code>errorCode 1</code></li><li><strong>Вебхуки:</strong> HTTP GET с checksum HMAC-SHA256, ACK 200, ретраи (PDF не задаёт — mock-конфиг)</li><li><strong>Состояния:</strong> <code>orderStatus 0…6</code>, <code>sessionTimeoutSecs</code> → <code>declinedByTimeout</code></li><li><strong>Сценарии:</strong> <code>X-Mock-Scenario</code> на <code>*.do</code> и форме, отказные карты вместо префиксов</li><li><strong>DX:</strong> <code>{errorCode,errorMessage}</code> + field/hint/doc, OpenAPI 3.1</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code>, без <code>verify-merchant</code> (GET query)</li></ul><h3 id="sber-mock-3105" tabindex="-1">sber-mock :3105 <a class="header-anchor" href="#sber-mock-3105" aria-label="Permalink to &quot;sber-mock :3105&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/ecomm/gw/partner/api/v1/{register,registerPreAuth,deposit,reverse,refund,decline}.do</code> JSON, hosted form + ACS <code>111111</code></li><li><strong>Auth:</strong> <code>userName</code>/<code>password</code> JSON, синтетические <code>SBERMOCKTEST</code>/<code>mockpass123</code></li><li><strong>Вебхуки:</strong> JSON POST без подписи, ACK 200, retry 3×60s</li><li><strong>Состояния:</strong> <code>orderStatus 0…6</code>, TTL 1200s, до 3 попыток оплаты</li><li><strong>Сценарии:</strong> официальные карты 101/116, <code>X-Mock-Scenario</code>, <code>/mock/time</code> для TTL</li><li><strong>DX:</strong> <code>{errorCode,errorMessage}</code> + field/hint/doc, errorCode mapping [VERIFY]/[FORK]</li><li><strong>Песочницы:</strong> RFC-001, без <code>verify-merchant</code></li></ul><h3 id="vtb-mock-3106" tabindex="-1">vtb-mock :3106 <a class="header-anchor" href="#vtb-mock-3106" aria-label="Permalink to &quot;vtb-mock :3106&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/openapi/smb/efcp/e-commerce/v1/{orders,preauth,complete,cancel,refunds}</code>, OAuth token endpoint</li><li><strong>Auth:</strong> OAuth 2.0 <code>client_credentials</code> + <code>Authorization: Bearer</code> + <code>X-IBM-Client-Id</code>, синтетические <code>vtbmocktest</code>/<code>mockpass123</code>, <code>amount.value</code> — decimal рубли</li><li><strong>Вебхуки:</strong> POST <code>{&quot;type&quot;:&quot;PAYMENT|REFUND&quot;,&quot;object&quot;:{…}}</code> без подписи, любой 2xx считается доставкой [FORK], retry 3×60s</li><li><strong>Состояния:</strong> ордер <code>CREATED → PAID → REFUNDED</code>, операция <code>NEW/CONFIRMED/RECONCILED</code>, TTL 20 мин</li><li><strong>Сценарии:</strong> <code>status-lowercase</code>, <code>reconciled</code>, синтетические [FORK]-карты (официальная истекла)</li><li><strong>DX:</strong> <code>{error, error_description}</code> + field/hint/doc, envelope [FORK]</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code> per-sandbox токены и ордеры</li></ul><h2 id="Кассы-и-ОФД" tabindex="-1">Кассы и ОФД <a class="header-anchor" href="#Кассы-и-ОФД" aria-label="Permalink to &quot;Кассы и ОФД&quot;">​</a></h2><h3 id="kassa-mock-3101-ofd-ferma" tabindex="-1">kassa-mock :3101 (OFD Ferma) <a class="header-anchor" href="#kassa-mock-3101-ofd-ferma" aria-label="Permalink to &quot;kassa-mock :3101 (OFD Ferma)&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/possystem/v1/{getToken,sell,sell_refund,sell_correction,buy,buy_refund,buy_correction,report,stats,ofd/*}</code></li><li><strong>Auth:</strong> <code>getToken</code> + TTL 12 ч</li><li><strong>Вебхуки:</strong> callback по документу, ретраи до 2xx</li><li><strong>Состояния:</strong> ККТ wait→done/fail, ОФД pending→sent/rejected, авансы/возвраты</li><li><strong>Сценарии:</strong> <code>fail</code>, <code>hang</code>, <code>ofd-queue</code>, <code>ofd-reject</code>, <code>mark-fail</code></li><li><strong>DX:</strong> формат Ferma + dry-run <code>/validate</code>, 54-ФЗ, НДС, маркировка</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code>, <code>verify-merchant</code></li></ul><h3 id="atol-mock-3103" tabindex="-1">atol-mock :3103 <a class="header-anchor" href="#atol-mock-3103" aria-label="Permalink to &quot;atol-mock :3103&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>/possystem/v4/{getToken, {group}/{operation}, {group}/report/{uuid}}</code>, decimal-рубли, страница чека <code>/receipts/{uuid}</code></li><li><strong>Auth:</strong> <code>getToken</code> → токен в заголовке <code>Token</code>, TTL 24 ч, идемпотентность <code>external_id</code> в пределах группы (replay возвращает прежний UUID)</li><li><strong>Вебхуки:</strong> callback на <code>service.callback_url</code>, без подписи, приёмник идемпотентен</li><li><strong>Состояния:</strong> очередь <code>wait → done|fail</code>, <code>payload</code> с ФД/ФП, ФН/ККТ</li><li><strong>Сценарии:</strong> <code>fail-</code>/<code>hang-</code> префиксы, <code>webhook-drop</code>, <code>/mock/time</code> для истечения токена</li><li><strong>DX:</strong> <code>{error:{code,text,type,error_id}}</code> + field/hint/doc</li><li><strong>Песочницы:</strong> собственные login/pass/группа АТОЛ per-sandbox</li></ul><h3 id="first-ofd-mock-3107-okassa" tabindex="-1">first-ofd-mock :3107 (OKassa) <a class="header-anchor" href="#first-ofd-mock-3107-okassa" aria-label="Permalink to &quot;first-ofd-mock :3107 (OKassa)&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>POST /getToken</code> + <code>/api/external/queue/v1/{transaction/{type},transaction/{requestId},status/{requestId},statuses}</code> + <code>/api/external/receipts</code></li><li><strong>Auth:</strong> <code>{login, pass}</code> (API-ключ UUID) → Bearer-токен 24 ч на виртуальных часах, <code>requestMetadata.userGroup</code> сверяется с каталогом, дефолты синтетические</li><li><strong>Вебхуки:</strong> unsigned POST на <code>requestMetadata.callbackUrl</code>, fallback <code>MOCK_FIRST_OFD_CALLBACK_URL</code> [FORK], любой 2xx = доставка [FORK], retry 3×60s, SSRF-политика ядра</li><li><strong>Состояния:</strong> <code>IN_PROGRESS → COMPLETED|ERROR</code>, <code>errorType</code> — слой ошибки, повторный openShift → <code>SHIFT_ALREADY_OPEN</code> [FORK]</li><li><strong>Сценарии:</strong> <code>kkt-error</code>, <code>api-error</code>, <code>getToken-error-quirk</code>, <code>webhook-drop</code></li><li><strong>DX:</strong> <code>{error:{code,text,layer}}</code> + field/hint/doc, подсказка про <code>EXPENCE</code></li><li><strong>Песочницы:</strong> заявки, смены, сценарии и часы per-sandbox</li></ul><h3 id="kontur-ofd-mock-3108" tabindex="-1">kontur-ofd-mock :3108 <a class="header-anchor" href="#kontur-ofd-mock-3108" aria-label="Permalink to &quot;kontur-ofd-mock :3108&quot;">​</a></h3><ul><li><strong>Протокол:</strong> read/reconciliation — организации, кассы, ФД, суммы в копейках, без создания чека и callback</li><li><strong>Auth:</strong> Sid + API key, креды только через env (в коде нет)</li><li><strong>Вебхуки:</strong> нет (read-only)</li><li><strong>Состояния:</strong> документы уже приняты ОФД, пагинация cursor</li><li><strong>Сценарии:</strong> синтетический каталог [FORK], cursor — неотрицательный индекс</li><li><strong>DX:</strong> ошибки как у провайдера, DX-поля — [FORK]</li><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code>, каталог независимо копируется per-sandbox</li></ul><h3 id="taxcom-mock-3109" tabindex="-1">taxcom-mock :3109 <a class="header-anchor" href="#taxcom-mock-3109" aria-label="Permalink to &quot;taxcom-mock :3109&quot;">​</a></h3><ul><li><strong>Протокол:</strong> <code>POST /API/v2/Login</code> с <code>Integrator-ID</code> → <code>Session-Token</code> TTL 300s sliding, <code>GET AccountList</code>, <code>GET NewDocuments</code> (10 суток, лимит 10 000, курсор по id, ошибки 3106/2203), write API не моделируется (405/404)</li><li><strong>Auth:</strong> синтетические <code>taxcommocktest</code>/<code>mockpass123</code>/<code>TAXCOMMOCKTEST</code>, форма тела [VERIFY], повторный Login выдаёт новый marker [FORK]</li><li><strong>Вебхуки:</strong> нет</li><li><strong>Состояния:</strong> фискальные документы (смены, состояние расчётов, чеки, БСО), демо-документы по смещению от базы стенда [FORK]</li><li><strong>Сценарии:</strong> хвост → пустой ответ, 3106 «нет доступной ККТ», 2203 «некорректный курсор»</li><li><strong>DX:</strong> конверт ошибки [VERIFY], поля ответа [FORK]</li><li><strong>Песочницы:</strong> owned-режим генерирует собственные mock-реквизиты</li></ul><h2 id="Общие-возможности-ядра" tabindex="-1">Общие возможности ядра <a class="header-anchor" href="#Общие-возможности-ядра" aria-label="Permalink to &quot;Общие возможности ядра&quot;">​</a></h2><ul><li><strong>Песочницы:</strong> <code>X-Mock-Sandbox</code> (request-local, RFC-001), <code>POST /sandboxes</code> (hosted: owner-token, TTL, лимиты), <code>/sandboxes/me/*</code>, <code>/mock/sandboxes</code>, <code>/mock/reset</code>, <code>/mock/state</code></li><li><strong>Экзаменатор:</strong> <code>POST /mock/verify-merchant</code> — активный экзаменатор вебхуков (там, где подпись применима)</li><li><strong>Часы:</strong> <code>POST /mock/time</code> (<code>+7d</code>, <code>+60d</code>) — TTL токенов, смены 24 ч, ФН, retry</li><li><strong>Журнал:</strong> <code>/admin/journal</code> с готовым <code>curl</code>, как мок понял запрос</li><li><strong>Наблюдаемость:</strong> <code>/admin</code> (+ журнал), <code>/health</code>/<code>/healthz</code>, OpenAPI 3.1 <code>/openapi.json</code>, управляющая поверхность под <code>MOCK_OPERATOR_TOKEN</code>, админка под <code>MOCK_ADMIN_TOKEN</code></li></ul>',28)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
